 function pick(i){selected=i;battle=null;render()}function combat(a){if(!battle||battle.finished)return;const dmg=[14,2,24,38][a];if(a===1){battle.hp=Math.min(100,battle.hp+10);battle.log.unshift(state.language==='fr'?'Défense activée. +10 HP':'Guard active. +10 HP')}else if(a===2){battle.towers[0]=Math.max(0,battle.towers[0]-dmg);battle.log.unshift((state.language==='fr'?'Tour ennemie attaquée : -':'Enemy tower attacked: -')+dmg+' · '+battle.towers[0]+' HP')}else if(battle.towers[0]>0){battle.log.unshift(state.language==='fr'?'La tour ennemie protège encore le château !':'The enemy tower still protects the castle!')}else{battle.castle=Math.max(0,battle.castle-dmg);battle.log.unshift((state.language==='fr'?'Assaut sur le château : -':'Castle assault: -')+dmg)}const enemy=a===1?4:7+Math.floor(Math.random()*10);battle.hp=Math.max(0,battle.hp-enemy);battle.minutes=Math.min(10,battle.minutes+1);battle.turn++;if(battle.castle<=0||battle.minutes>=10||battle.hp<=0){finish(battle.castle<=0)}render()}function finish(win){if(!battle||battle.finished)return;battle.finished=true;state.matches++;if(win){state.wins++;state.lp=Math.min(100,state.lp+18);state.guildWins++;state.streak++;battle.log.unshift(state.language==='fr'?'Victoire impériale ! +18 LP':'Imperial victory! +18 LP')}else{state.lp=Math.max(0,state.lp-12);state.streak=0;battle.log.unshift(state.language==='fr'?'Défaite. -12 LP':'Defeat. -12 LP')}save()}
