 function tutorial(){const lessons=state.language==='fr'?[['◆','Le champ de bataille','Repérez les tours, les routes et le château impérial.'],['⚔','Combat','Frappe, garde, aptitudes et ultime ont chacun un rôle.'],['🏰','Objectifs','Détruire les tours ouvre l’accès au château.'],['👥','Travail d’équipe','Composée avec tes coéquipiers et protège leurs flancs.'],['▲','Progression','Victoires +18 LP, défaites -12 LP ; promotion à 100 LP.'],['◉','Communication','Utilise les canaux mondial, clan et amis pour coordonner.']]:[['◆','The battlefield','Read lanes, towers and the imperial castle.'],['⚔','Combat','Strike, guard, abilities and ultimate each have a role.'],['🏰','Objectives','Destroy towers to open a path to the castle.'],['👥','Teamwork','Build with teammates and protect their flanks.'],['▲','Progression','Wins add 18 LP and losses remove 12 LP; promote at 100 LP.'],['◉','Communication','Use world, clan and friend channels to coordinate.']];return `<div class="section-head"><h2>${state.language==='fr'?'Académie du Rift':'Rift Academy'}</h2><small>${state.language==='fr'?'Formation complète 3D':'Complete 3D training'}</small></div><div class="tutorial-grid">${lessons.map(x=>`<div class="lesson"><div class="lesson-icon">${x[0]}</div><div><h3>${x[1]}</h3><p>${x[2]}</p></div></div>`).join('')}</div><button class="button primary" style="margin-top:16px" onclick="completeTutorial()">${t('complete')}</button>`}function completeTutorial(){state.tutorialDone=true;save();toast(state.language==='fr'?'Formation terminée !':'Training complete!')}
