const { spawn } = require('node:child_process');
const fs = require('node:fs');
const profile = `/tmp/opencode/chrome-riftbound-${process.pid}`;
const chrome = spawn('chromium', ['--headless', '--no-sandbox', '--disable-gpu', '--disable-dev-shm-usage', '--no-first-run', '--no-default-browser-check', '--remote-debugging-port=0', `--user-data-dir=${profile}`, 'http://127.0.0.1:4173/'], { stdio: 'ignore' });
let socket;
const errors = [];
async function waitFor(fn, timeout = 10000) {
  const until = Date.now() + timeout;
  while (Date.now() < until) {
    try { const result = await fn(); if (result) return result; } catch {}
    await new Promise(resolve => setTimeout(resolve, 100));
  }
  throw new Error('Timed out waiting for browser endpoint');
}
(async () => {
 try {
  const targets = await waitFor(async () => { const r = await fetch('http://127.0.0.1:9222/json/list'); return r.ok ? r.json() : null; });
  const target = targets.find(t => t.type === 'page');
  socket = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => { socket.onopen = resolve; socket.onerror = reject; });
  let seq = 0;
  const pending = new Map();
  socket.onmessage = event => {
    const msg = JSON.parse(event.data);
    if (msg.method === 'Runtime.exceptionThrown') errors.push(msg.params.exceptionDetails.text);
    if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
  };
  const cdp = (method, params = {}) => new Promise(resolve => { const id = ++seq; pending.set(id, resolve); socket.send(JSON.stringify({ id, method, params })); });
  const evaluate = async expression => {
    const result = await cdp('Runtime.evaluate', { expression, awaitPromise: true, returnByValue: true });
    if (result.result.exceptionDetails) throw new Error(result.result.exceptionDetails.text);
    return result.result.result.value;
  };
  await cdp('Runtime.enable');
  await waitFor(async () => (await evaluate("document.querySelector('.hero h1')?.textContent"))?.length);
  const assert = (condition, name) => { if (!condition) throw new Error(`FAIL: ${name}`); console.log(`PASS: ${name}`); };
  assert((await evaluate("document.querySelector('.hero h1').textContent.includes('Gold')")), 'initial English dashboard');
  await evaluate("document.querySelector('.lang-btn').click()");
  assert(await evaluate("document.querySelector('.hero h1').textContent.includes('Or')"), 'French language toggle');
  await evaluate("document.querySelector('.nav button[onclick=\"go('chat')\"]').click()");
  await evaluate("document.querySelector('#chatInput').value='persist check'; document.querySelector('.chat-input .button').click()");
  assert(await evaluate("document.querySelector('.messages').textContent.includes('persist check')"), 'chat send renders message');
  assert(await evaluate("JSON.parse(localStorage.getItem('riftbound-chat')).world.some(m=>m[1]==='persist check')"), 'chat persists locally');
  await evaluate("document.querySelector('.nav button[onclick=\"go('friends')\"]').click(); document.querySelector('.section-head .button').click(); document.querySelector('#modalInput').value='TestFriend'; document.querySelector('#modal .primary').click()");
  assert(await evaluate("document.querySelector('.friend-row b') && [...document.querySelectorAll('.friend-row b')].some(e=>e.textContent==='TestFriend')"), 'friend invitation adds local friend');
  await evaluate("document.querySelector('.nav button[onclick=\"go('tutorial')\"]').click(); document.querySelector('.section-head + .tutorial-grid + button').click()");
  assert(await evaluate("JSON.parse(localStorage.getItem('riftbound-save')).tutorialDone"), 'tutorial completion persists');
  await evaluate("document.querySelector('.nav button[onclick=\"go('play')\"]').click()");
  assert(await evaluate("document.querySelector('.arena-top').textContent.includes('LIVE')"), 'battle starts live');
  await evaluate("combat(0)");
  assert(await evaluate("document.querySelector('.battle-log')?.textContent.includes('protects') || document.body.textContent.includes('protège')"), 'tower blocks castle assault');
  for (let i=0; i<5; i++) await evaluate('combat(2)');
  assert(await evaluate("document.querySelector('.fighter-label').textContent.includes('exposé') || document.querySelector('.fighter-label').textContent.includes('Exposed')"), 'destroying tower exposes castle');
  for (let i=0; i<10 && await evaluate("document.querySelector('.arena-top').textContent.includes('LIVE')"); i++) await evaluate('combat(1)');
  assert(await evaluate("document.querySelector('.arena-top').textContent.includes('TERMINÉ') || document.querySelector('.arena-top').textContent.includes('FINISHED')"), 'battle ends at or before 10 minutes');
  const matchCount = await evaluate("JSON.parse(localStorage.getItem('riftbound-save')).matches");
  await evaluate("combat(0)");
  assert(await evaluate("JSON.parse(localStorage.getItem('riftbound-save')).matches") === matchCount, 'finished match cannot award progression twice');
  await evaluate("document.querySelector('.icon-btn').click(); document.querySelector('#snoxName').value='Verifier'; document.querySelector('#snoxPass').value='secure-pass-123'; document.querySelector('#modal .primary').click()");
  await waitFor(async () => await evaluate("!document.querySelector('#modal')"));
  const account = await evaluate("JSON.parse(localStorage.getItem('riftbound-snox')).Verifier");
  assert(!!account?.salt && !!account?.hash && !account?.pass, 'SNOX account stores salted hash, not plaintext password');
  await evaluate("document.querySelector('.icon-btn').click(); document.querySelector('#snoxName').value='verifier'; document.querySelector('#snoxPass').value='wrong-pass-123'; document.querySelector('.modal-actions .gold').click()");
  await waitFor(async () => await evaluate("document.querySelector('.toast')?.classList.contains('show')"));
  assert(await evaluate("document.querySelector('#modal') !== null"), 'incorrect SNOX password is rejected');
  await evaluate("document.querySelector('#snoxPass').value='secure-pass-123'; document.querySelector('.modal-actions .gold').click()");
  await waitFor(async () => await evaluate("!document.querySelector('#modal')"));
  assert(await evaluate("document.querySelector('.hero') === null && localStorage.getItem('riftbound-save').includes('Verifier')"), 'SNOX sign-in restores account locally');
  assert(errors.length === 0, `no browser runtime exceptions (${errors.join('; ')})`);
 } catch (error) { console.error(error.stack || error); process.exitCode = 1; }
 finally { if (socket) socket.close(); chrome.kill('SIGTERM'); try { fs.rmSync(profile, { recursive: true, force: true }); } catch {} }
})();

